const items = $input.all();

const entradas = items.filter(i => i.json.tipo === 'entrada').length;
const salidas = items.filter(i => i.json.tipo === 'salida').length;
const ventas = items.filter(i => i.json.tipo === 'venta').length;

const filasHTML = items.map(i => `
    <tr>
        <td>${i.json.tipo}</td>
        <td>${i.json.codigo}</td>
        <td>${i.json.producto}</td>
        <td>${i.json.cantidad}</td>
        <td>${i.json.proveedor || i.json.notas || '—'}</td>
        <td>${i.json.motivo || '—'}</td>
        <td>${i.json.fecha ? i.json.fecha.split('T')[0] : '—'}</td>
    </tr>
`).join('');

const telegramMsg = ` Registro de movimientos
${new Date().toLocaleDateString('es-GT')}

Total movimientos: ${items.length}
Entradas: ${entradas}
Salidas: ${salidas}
Ventas: ${ventas}

Últimos 5:
${items.slice(0,5).map(i =>
    ` ${i.json.tipo.toUpperCase()} - ${i.json.producto} (${i.json.cantidad} uds)`
).join('\n')}

Ver reporte completo en su correo.`;

return [{
    json: {
        total: items.length,
        entradas,
        salidas,
        ventas,
        filas_html: filasHTML,
        telegram: telegramMsg
    }
}];
